    const [s, x] = line.split(' ').map(BigInt);
    const result = solve(s, x);
    console.log(result.toString());
    rl.close();
});

function solve(s, x) {
    if (s < x) return 0n;
    const diff = s - x;
    if (diff % 2n !== 0n) return 0n;
    const d = diff / 2n;
    if ((d & x) !== 0n) return 0n;
    let count = 0n;
    let temp = x;
    while (temp > 0n) {
        if (temp & 1n) count++;
        temp >>= 1n;
    }
    let ans = 1n << count;
    if (d === 0n) ans -= 2n;
    return ans < 0n ? 0n : ans;
}
